package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.os.*;import androidx.media3.common.*;import androidx.media3.datasource.*;import androidx.media3.exoplayer.*;import androidx.media3.exoplayer.hls.*;import androidx.media3.ui.PlayerView;import com.tiviloom.mobile.BroadcastMediaSources;import androidx.media3.exoplayer.analytics.AnalyticsListener;import androidx.media3.exoplayer.source.*;
/** Local captured TS stays outside the repository. Audio is disabled to isolate keyframe parsing. */
public final class NonIdrPlaybackTest extends NativePlayerTest {
 ExoPlayer probe;PlayerView surface;volatile long mediaBytes;
 int frames(){return probe.getVideoDecoderCounters()==null?0:probe.getVideoDecoderCounters().renderedOutputBufferCount;}
 void begin(boolean tolerant)throws Exception{onMain(()->{if(probe!=null){surface.setPlayer(null);probe.release();}mediaBytes=0;probe=new ExoPlayer.Builder(activity).setRenderersFactory(new DefaultRenderersFactory(activity).setEnableDecoderFallback(true)).build();probe.setTrackSelectionParameters(probe.getTrackSelectionParameters().buildUpon().setTrackTypeDisabled(C.TRACK_TYPE_AUDIO,true).build());MediaItem item=MediaItem.fromUri("http://10.0.2.2:18888/non-idr.m3u8");DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setTransferListener(new TransferListener(){public void onTransferInitializing(DataSource source,DataSpec spec,boolean network){} public void onTransferStart(DataSource source,DataSpec spec,boolean network){} public void onTransferEnd(DataSource source,DataSpec spec,boolean network){} public void onBytesTransferred(DataSource source,DataSpec spec,boolean network,int bytes){if(spec.uri.getPath().endsWith(".ts"))mediaBytes+=bytes;}});probe.setMediaSource(tolerant?BroadcastMediaSources.create(http,item):new HlsMediaSource.Factory(http).createMediaSource(item));surface.setPlayer(probe);probe.prepare();probe.play();return true;});}
 @Override public void onStart(){try{activity=startActivitySync(new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.NativePlaybackActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("payload","{\"url\":\"http://10.0.2.2:18888/demo.mp4\"}"));waitFor(()->renderedVideo()>0);onMain(()->{surface=(PlayerView)field("playerView");host().getClass().getMethod("release").invoke(host());return true;});
 check("default extractor reproduces missing first frame on non-IDR TS",()->{begin(false);waitFor(()->mediaBytes>1000000);SystemClock.sleep(1000);require(onMain(()->frames()==0&&probe.getPlayerError()==null),"Default extractor unexpectedly produced video or a playback error");});
 check("broadcast extractor displays non-IDR TS frames",()->{begin(true);waitFor(()->frames()>0);});
 }catch(Throwable e){failed++;report.append("FATAL ").append(e.toString());}finally{runOnMainSync(()->{if(probe!=null){surface.setPlayer(null);probe.release();}if(activity!=null)activity.finish();});}Bundle out=new Bundle();out.putString("stream",report+"\nPASSED="+passed+" FAILED="+failed+"\n");finish(failed==0?-1:0,out);}
}
